package jp.schoolboard;
import android.content.*;import org.json.*;import java.time.*;import java.util.*;
final class Store {
 static android.content.SharedPreferences p(Context c){return c.getSharedPreferences("board",0);}
 static JSONArray tasks(Context c){try{return new JSONArray(p(c).getString("tasks","[]"));}catch(Exception e){return new JSONArray();}}
 static void save(Context c,JSONArray a){p(c).edit().putString("tasks",a.toString()).apply();BoardWidget.refresh(c);}
 static JSONObject data(Context c){try{return new JSONObject(p(c).getString("data","{}"));}catch(Exception e){return new JSONObject();}}
 static void importData(Context c,String raw)throws Exception{JSONObject d=new JSONObject(raw);for(String key:new String[]{"lessons","events"}){JSONArray a=d.getJSONArray(key);for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);if(o.getString("title").trim().isEmpty())throw new Exception("名前が空です");if(key.equals("lessons")){int day=o.getInt("day");if(day<1||day>7)throw new Exception("曜日は1〜7です");LocalTime.parse(o.getString("start"));LocalTime.parse(o.getString("end"));LocalDate.parse(o.getString("from"));LocalDate.parse(o.getString("to"));}else LocalDate.parse(o.getString("date"));}}p(c).edit().putString("data",d.toString()).apply();BoardWidget.refresh(c);}
 static List<JSONObject> pending(Context c){List<JSONObject> l=new ArrayList<>();JSONArray a=tasks(c);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&!o.optBoolean("done"))l.add(o);}l.sort(Comparator.comparing(o->o.optString("due")));return l;}
 static void toggle(Context c,String id){JSONArray a=tasks(c);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optString("id").equals(id))try{o.put("done",!o.optBoolean("done"));}catch(Exception ignored){}}save(c,a);}
 static List<String> lines(Context c,String tab){List<String> out=new ArrayList<>();LocalDate today=LocalDate.now();JSONArray a=data(c).optJSONArray(tab);if(a==null)return out;List<JSONObject> list=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;if(tab.equals("lessons")){if(o.optInt("day")==today.getDayOfWeek().getValue()&&today.toString().compareTo(o.optString("from"))>=0&&today.toString().compareTo(o.optString("to"))<=0)list.add(o);}else if(o.optString("date").compareTo(today.toString())>=0)list.add(o);}list.sort(Comparator.comparing(o->o.optString(tab.equals("lessons")?"start":"date")));for(JSONObject o:list)out.add(tab.equals("lessons")?o.optString("start")+"–"+o.optString("end")+"  "+o.optString("title")+"\n"+o.optString("room"):o.optString("date")+"  "+o.optString("title"));return out;}
}